import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../build/host.gen.ts';

const fresh = async () => { const h: any = await createHost(); return h; };
const view = (status: string, task0: string, task1: string, retried0 = false, retried1 = false) => ({ status, task0, task1, retried0, retried1 });

test('initial state and queries', async () => {
  const h = await fresh();
  assert.deepEqual(await h.run(), view('idle', 'idle', 'idle'));
  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
  assert.equal(await h.worker('nobody'), null);
  assert.equal((await h.workDone('nobody')).ok, false);
  assert.equal((await h.cancel()).ok, false);
  await h.__dispose();
});

test('start, both complete', async () => {
  const h = await fresh();
  assert.deepEqual(await h.start(), { ok: true });
  assert.equal((await h.start()).ok, false);
  const msgs = await h.inFlight();
  assert.equal(msgs.length, 2);
  assert.deepEqual(msgs.map((m: any) => [m.from, m.to, m.action, m.data]).sort(), [['run', 'worker0', 'Assign', {}], ['run', 'worker1', 'Assign', {}]]);
  assert.deepEqual(await h.run(), view('running', 'assigned', 'assigned'));
  assert.equal((await h.workDone('worker0')).ok, false);
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker1'), { status: 'busy' });
  assert.deepEqual(await h.workDone('worker0'), { ok: true });
  const [r] = await h.inFlight();
  assert.deepEqual([r.from, r.to, r.action, r.data], ['worker0', 'run', 'Report', { task: 0, outcome: 'completed' }]);
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('running', 'completed', 'assigned'));
  await h.workDone('worker1');
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('completed', 'completed', 'completed'));
  await h.__dispose();
});

test('first failure is retried, second is recorded', async () => {
  const h = await fresh();
  await h.start();
  await h.deliverAll();
  await h.workFailed('worker1');
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('running', 'assigned', 'assigned', false, true));
  assert.deepEqual(await h.worker('worker1'), { status: 'busy' });
  await h.workFailed('worker1');
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('running', 'assigned', 'failed', false, true));
  await h.workDone('worker0');
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('failed', 'completed', 'failed', false, true));
  await h.__dispose();
});

test('retry then success', async () => {
  const h = await fresh();
  await h.start();
  await h.deliverAll();
  await h.workFailed('worker0');
  await h.deliver((await h.inFlight())[0].id);
  const [a] = await h.inFlight();
  assert.deepEqual([a.from, a.to, a.action, a.data], ['run', 'worker0', 'Assign', {}]);
  await h.deliverAll();
  await h.workDone('worker0');
  await h.workDone('worker1');
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('completed', 'completed', 'completed', true, false));
  await h.__dispose();
});

test('failure while cancelling is recorded', async () => {
  const h = await fresh();
  await h.start();
  await h.deliverAll();
  await h.workFailed('worker1');
  await h.cancel();
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('failed', 'cancelled', 'failed'));
  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
  await h.__dispose();
});

test('cancel before assign arrives', async () => {
  const h = await fresh();
  await h.start();
  await h.cancel();
  const aborts = (await h.inFlight()).filter((m: any) => m.action === 'Abort');
  for (const a of aborts) await h.deliver(a.id);
  assert.deepEqual(await h.run(), view('cancelling', 'assigned', 'assigned'));
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker0'), { status: 'busy' });
  await h.workDone('worker0');
  await h.workDone('worker1');
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('completed', 'completed', 'completed'));
  await h.__dispose();
});

