import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../build/host.gen.ts';

const fresh = async () => { const h: any = await createHost(); return h; };
const view = (status: string, task0: string, task1: string, retried0 = false, retried1 = false, processed = 0) => ({ status, task0, task1, retried0, retried1, processed });

test('initial state and queries', async () => {
  const h = await fresh();
  assert.deepEqual(await h.run(), view('idle', 'idle', 'idle'));
  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
  assert.equal(await h.worker('nobody'), null);
  assert.equal((await h.workDone('nobody', 1)).ok, false);
  assert.equal((await h.cancel()).ok, false);
  await h.__dispose();
});

test('start, both complete, items counted', async () => {
  const h = await fresh();
  assert.deepEqual(await h.start(), { ok: true });
  assert.equal((await h.start()).ok, false);
  const msgs = await h.inFlight();
  assert.equal(msgs.length, 2);
  assert.deepEqual(msgs.map((m: any) => [m.from, m.to, m.action, m.data]).sort(), [['run', 'worker0', 'Assign', {}], ['run', 'worker1', 'Assign', {}]]);
  assert.deepEqual(await h.run(), view('running', 'assigned', 'assigned'));
  assert.equal((await h.workDone('worker0', 1)).ok, false);
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker1'), { status: 'busy' });
  for (const bad of [0, 3, -1, 1.5]) assert.equal((await h.workDone('worker0', bad)).ok, false);
  assert.deepEqual(await h.worker('worker0'), { status: 'busy' });
  assert.deepEqual(await h.workDone('worker0', 2), { ok: true });
  const [r] = await h.inFlight();
  assert.deepEqual([r.from, r.to, r.action, r.data], ['worker0', 'run', 'Report', { task: 0, outcome: 'completed', items: 2 }]);
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('running', 'completed', 'assigned', false, false, 2));
  await h.workDone('worker1', 1);
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('completed', 'completed', 'completed', false, false, 3));
  await h.__dispose();
});

test('first failure is retried, second is recorded', async () => {
  const h = await fresh();
  await h.start();
  await h.deliverAll();
  await h.workFailed('worker1');
  const [r] = await h.inFlight();
  assert.deepEqual(r.data, { task: 1, outcome: 'failed', items: 0 });
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('running', 'assigned', 'assigned', false, true));
  assert.deepEqual(await h.worker('worker1'), { status: 'busy' });
  await h.workFailed('worker1');
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('running', 'assigned', 'failed', false, true));
  await h.workDone('worker0', 2);
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('failed', 'completed', 'failed', false, true, 2));
  await h.__dispose();
});

test('retry then success', async () => {
  const h = await fresh();
  await h.start();
  await h.deliverAll();
  await h.workFailed('worker0');
  await h.deliver((await h.inFlight())[0].id);
  const [a] = await h.inFlight();
  assert.deepEqual([a.from, a.to, a.action, a.data], ['run', 'worker0', 'Assign', {}]);
  await h.deliverAll();
  await h.workDone('worker0', 2);
  await h.workDone('worker1', 2);
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('completed', 'completed', 'completed', true, false, 4));
  await h.__dispose();
});

test('failure while cancelling is recorded', async () => {
  const h = await fresh();
  await h.start();
  await h.deliverAll();
  await h.workFailed('worker1');
  await h.cancel();
  const abort = (await h.inFlight()).find((m: any) => m.action === 'Abort');
  await h.deliver(abort.id);
  const rep = (await h.inFlight()).find((m: any) => m.from === 'worker0');
  assert.deepEqual(rep.data, { task: 0, outcome: 'cancelled', items: 0 });
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('failed', 'cancelled', 'failed'));
  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
  await h.__dispose();
});

test('timeout fails the task, aborts the worker, ignores the late report', async () => {
  const h = await fresh();
  assert.equal((await h.taskTimeout(0)).ok, false);
  await h.start();
  await h.deliverAll();
  assert.equal((await h.taskTimeout(2)).ok, false);
  assert.equal((await h.taskTimeout(-1)).ok, false);
  assert.deepEqual(await h.taskTimeout(0), { ok: true });
  assert.equal((await h.taskTimeout(0)).ok, false);
  assert.deepEqual(await h.run(), view('running', 'failed', 'assigned'));
  const msgs = await h.inFlight();
  assert.deepEqual(msgs.map((m: any) => [m.from, m.to, m.action, m.data]), [['run', 'worker0', 'Abort', {}]]);
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
  assert.deepEqual(await h.run(), view('running', 'failed', 'assigned'));
  await h.workDone('worker1', 1);
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('failed', 'failed', 'completed', false, false, 1));
  assert.equal((await h.taskTimeout(1)).ok, false);
  await h.__dispose();
});

test('late completion after timeout is ignored and not counted', async () => {
  const h = await fresh();
  await h.start();
  await h.deliverAll();
  await h.workDone('worker1', 2);
  await h.taskTimeout(1);
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('running', 'assigned', 'failed'));
  await h.cancel();
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('failed', 'cancelled', 'failed'));
  await h.__dispose();
});

test('cancel before assign arrives', async () => {
  const h = await fresh();
  await h.start();
  await h.cancel();
  const aborts = (await h.inFlight()).filter((m: any) => m.action === 'Abort');
  for (const a of aborts) await h.deliver(a.id);
  assert.deepEqual(await h.run(), view('cancelling', 'assigned', 'assigned'));
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker0'), { status: 'busy' });
  await h.workDone('worker0', 1);
  await h.workDone('worker1', 1);
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('completed', 'completed', 'completed', false, false, 2));
  await h.__dispose();
});

